    const rawRequired = this.getRequiredModelName();
    const requiredModels = Array.isArray(rawRequired) ? rawRequired : [rawRequired];

    const missingModels: string[] = [];

    requiredModels.forEach(modelName => {
      if (!mainProcess.models[modelName]) {
        missingModels.push(modelName);
      }
    });

    if (missingModels.length > 0) {
      const availableModels = Object.keys(mainProcess.models).join(", ");
      throw new Error(`Model Check Failed: Missing required models [${missingModels.join(", ")}]. Available models: [${availableModels}]`);
    }

